/**
 * Investigation cases (T049): a case links events, recording clips and notes from several cameras. A clip is a
 * bookmark into the NVR until an export job preserves a copy; footage the NVR no longer has is reported as missing.
 */
import { api, apiUrl, del, get, patch, post } from './client';

export type CaseStatus = 'open' | 'in_review' | 'closed';
export type CaseItemKind = 'event' | 'clip' | 'note' | 'snapshot';
export type Preservation = 'preserved' | 'preserving' | 'nvr_only' | 'missing' | 'unknown' | 'not_in_bundle' | 'none';

export const CASE_STATUS_LABEL: Record<CaseStatus, string> = { open: 'פתוח', in_review: 'בבדיקה', closed: 'סגור' };
export const PRESERVATION_LABEL: Record<Preservation, string> = {
  preserved: 'עותק שמור',
  preserving: 'מעתיק מה־NVR…',
  nvr_only: 'סימנייה ל־NVR בלבד',
  missing: 'חסר: ה־NVR כבר לא מחזיק את הקטע',
  unknown: 'לא נבדק מול ה־NVR',
  not_in_bundle: 'לא נכלל בחבילת המקור (סימנייה בלבד)',
  none: '',
};

export interface CaseCounts {
  items: number;
  events: number;
  clips: number;
  notes: number;
  snapshots: number;
  preserved: number;
}

export interface Case {
  id: string;
  title: string;
  description: string;
  status: CaseStatus;
  tags: string[];
  owner_user_id: string;
  owner_username: string;
  revision: number;
  created_at: string;
  updated_at: string;
  closed_at: string | null;
  counts: CaseCounts;
  /** T050 import: 'imported' = the case came from an evidence bundle; provenance says from where. */
  origin?: 'local' | 'imported';
  provenance?: CaseProvenance | null;
}

/** Where an imported case came from (recorded at import; the bundle verified cleanly then). */
export interface CaseProvenance {
  source_installation_id: string | null;
  source_app_version: string | null;
  exported_at: string | null;
  exported_by: string | null;
  exported_by_display: string | null;
  timezone: string | null;
  this_installation: boolean | null;
  confirmed_by_signature: boolean;
  basis: 'installation_id' | 'signing_key' | 'unknown';
  /** this_confirmed = signed by a key of this installation; this_claimed = our (public) id without our signature. */
  producer?: Producer;
  bundle_sha256: string;
  bundle_bytes: number;
  bundle_name: string | null;
  signature: { present: boolean; valid: boolean; trust: SignatureVerdict['trust']; kid: string | null; known: boolean; retired: boolean | null };
  verification: { ok: boolean; files: number; schema: string | null; verified_at: string };
  source_case: { id: string | null; title: string | null; status: string | null; owner_username: string | null; created_at: string | null; updated_at: string | null };
  imported_at: string;
  imported_by: string | null;
  files_stored: number;
  bytes_stored: number;
  skipped_at_source: number;
}

/** What the bundle said about an imported item: the source camera is a name only, never a camera here. */
export interface ItemOrigin {
  bundle_sha256: string;
  source_installation_id: string | null;
  source_item_id: string | null;
  kind: CaseItemKind;
  camera_id: string | null;
  camera_name: string | null;
  added_by: string | null;
  created_at: string | null;
  preservation: string | null;
  in_bundle: boolean;
  stored: boolean;
}

export interface CaseItem {
  id: string;
  case_id: string;
  kind: CaseItemKind;
  camera_id: string | null;
  camera_name: string | null;
  event_id: string | null;
  event: { type: string; occurred_at: string; ended_at: string | null; severity: string; confidence: string; thumbnail?: string; acked_at: string | null; source: string } | null;
  export_job_id: string | null;
  from_at: string | null;
  to_at: string | null;
  note: string;
  added_by_username: string;
  created_at: string;
  preservation: Preservation;
  export: { id: string; state: string; progress: number; download_ready: boolean; error: string | null } | null;
  file_path?: string | null;
  file_sha256?: string | null;
  file_url?: string | null;
  imported?: boolean;
  origin?: ItemOrigin | null;
}

export interface CaseDetail extends Case {
  items: CaseItem[];
  hidden_items: number;
  can_manage: boolean;
  /** false when the NVR could not be asked (no NVR configured or check=false): preservation reads "unknown". */
  checked: boolean;
}

export interface NewCaseItem {
  kind: CaseItemKind;
  event_id?: string;
  camera_id?: string;
  from_at?: string;
  to_at?: string;
  note?: string;
}

export function listCases(opts: { status?: CaseStatus; q?: string } = {}) {
  const p = new URLSearchParams();
  if (opts.status) p.set('status', opts.status);
  if (opts.q) p.set('q', opts.q);
  const qs = p.toString();
  return get<{ cases: Case[]; can_manage: boolean; can_import?: boolean }>(`cases${qs ? `?${qs}` : ''}`);
}
export const createCase = (body: { title: string; description?: string; tags?: string[]; status?: CaseStatus }) => post<Case>('cases', body);
export const getCase = (id: string, check = true) => get<CaseDetail>(`cases/${id}${check ? '' : '?check=false'}`);
export const updateCase = (id: string, body: { revision: number; title?: string; description?: string; tags?: string[]; status?: CaseStatus }) => patch<Case>(`cases/${id}`, body);
export const deleteCase = (id: string) => del(`cases/${id}`);
export const addCaseItem = (id: string, body: NewCaseItem) => post<CaseItem>(`cases/${id}/items`, body);
export const removeCaseItem = (id: string, itemId: string) => del(`cases/${id}/items/${itemId}`);
export const preserveCaseItem = (id: string, itemId: string) => post<CaseItem>(`cases/${id}/items/${itemId}/preserve`);

/** A bookmark on the playback timeline (T049): an event / clip item of a case, for one camera and local day.
 * `nvr` = the NVR still has to serve it (no copy yet); preserved / preserving follow the export job. */
export interface Bookmark {
  id: string;
  case_id: string;
  case_title: string;
  case_status: CaseStatus;
  kind: CaseItemKind;
  event_id: string | null;
  from_at: string;
  to_at: string;
  note: string;
  added_by_username: string;
  preservation: 'preserved' | 'preserving' | 'nvr';
}
export const BOOKMARK_LABEL: Record<Bookmark['preservation'], string> = { preserved: 'עותק שמור', preserving: 'מעתיק מה־NVR…', nvr: 'סימנייה ל־NVR' };
export const listBookmarks = (cameraId: string, date: string) => get<{ bookmarks: Bookmark[] }>(`cases/bookmarks?camera_id=${encodeURIComponent(cameraId)}&date=${encodeURIComponent(date)}`);

const isoSec = (d: Date) => d.toISOString().replace(/\.\d{3}Z$/, 'Z');
/** A clip bookmark around an instant (default 15 s before, 45 s after). */
export const clipAround = (at: Date, beforeS = 15, afterS = 45) => ({ from_at: isoSec(new Date(at.getTime() - beforeS * 1000)), to_at: isoSec(new Date(at.getTime() + afterS * 1000)) });

/** Evidence bundle of a case (T050): one ZIP with a manifest and a SHA-256 per file; verification recomputes them. */
export interface Bundle {
  name: string;
  bytes: number;
  created_at: string;
  download_url: string;
  sha256?: string;
  files?: number;
  skipped?: { item_id: string; reason: string }[];
  /** Key id the bundle's manifest was signed with (T067); null for bundles made before 0.1.40. */
  signed?: string | null;
  signature?: { alg: string; kid: string };
}
/** Verdict on the manifest signature: integrity since export, and whether the key belongs to this installation. */
export interface SignatureVerdict {
  present: boolean;
  valid: boolean;
  kid?: string | null;
  known?: boolean;
  retired?: boolean | null;
  trust: 'installation' | 'embedded_key_only' | 'unsigned';
  reason?: string | null;
}
export interface SigningInfo {
  alg: string;
  active: string | null;
  keys: { kid: string; alg: string; public_key: string; created_at: string; retired_at: string | null }[];
  trust: string;
  can_rotate: boolean;
}
export type BundleFileStatus = 'ok' | 'mismatch' | 'missing' | 'corrupt';
export const FILE_STATUS_LABEL: Record<BundleFileStatus, string> = { ok: 'תואם', mismatch: 'שונה', missing: 'חסר', corrupt: 'פגום' };
/** The producing installation as the manifest names it; `confirmed_by_signature` = signed by a key of this installation. */
export interface BundleOrigin {
  installation_id: string | null;
  app_version: string | null;
  exported_at: string | null;
  exported_by: string | null;
  exported_by_display: string | null;
  timezone: string | null;
  this_installation: boolean | null;
  basis: 'installation_id' | 'signing_key' | 'unknown';
  confirmed_by_signature: boolean;
  producer?: Producer;
}
export type Producer = 'this_confirmed' | 'this_claimed' | 'other' | 'unknown';
/** Who made a bundle, worded honestly: the installation id is public, only a signature of this installation confirms it. */
export function producerOf(o: { producer?: Producer; this_installation: boolean | null; confirmed_by_signature: boolean } | null | undefined): Producer {
  if (!o) return 'unknown';
  if (o.producer) return o.producer;
  return o.this_installation === true ? (o.confirmed_by_signature ? 'this_confirmed' : 'this_claimed') : o.this_installation === false ? 'other' : 'unknown';
}
export const PRODUCER_LABEL: Record<Producer, string> = {
  this_confirmed: 'התקנה זו (מאושר בחתימה)',
  this_claimed: 'התקנה זו לפי המזהה בלבד (לא מאושר בחתימה)',
  other: 'התקנה אחרת',
  unknown: 'לא ידוע (חבילה ללא מזהה התקנה)',
};
export interface BundleVerification {
  ok: boolean;
  schema: string | null;
  schema_version?: number | null;
  supported?: boolean;
  case?: string;
  generated_at?: string;
  manifest_ok: boolean | null;
  files: { path: string; status: BundleFileStatus; expected: string; actual: string | null; bytes?: number | null }[];
  extra: string[];
  errors: string[];
  signature?: SignatureVerdict;
  authenticity?: string;
  origin?: BundleOrigin | null;
  counts?: Record<BundleFileStatus | 'extra', number>;
  /** Plain-language verdict: a matching hash = unchanged since export, not proof that the footage is genuine. */
  summary?: string;
  bundle?: { sha256: string; bytes: number; name: string | null };
  already_imported?: { case_id: string; title: string } | null;
  importable?: boolean;
}
export interface BundleImport {
  case: Case;
  items: number;
  files: number;
  bytes: number;
  bundle: { sha256: string; bytes: number; name: string | null };
  report: Pick<BundleVerification, 'ok' | 'summary' | 'counts' | 'origin' | 'signature' | 'schema' | 'schema_version' | 'authenticity'>;
}
export interface CaseIntegrity {
  case_id: string;
  checked_at: string;
  ok: boolean;
  files: { item_id: string; kind: CaseItemKind; status: 'ok' | 'mismatch' | 'missing'; expected: string; actual: string | null }[];
  hidden_items: number;
  note: string;
}
export const getSigning = () => get<SigningInfo>('evidence/signing');
export const rotateSigning = () => post<SigningInfo>('evidence/signing/rotate');
export const createBundle = (id: string) => post<Bundle>(`cases/${id}/bundle`);
export const listBundles = (id: string) => get<{ bundles: Bundle[] }>(`cases/${id}/bundles`);
export const bundleUrl = (id: string, name: string) => apiUrl(`cases/${id}/bundles/${name}`);
export const caseItemFileUrl = (id: string, itemId: string) => apiUrl(`cases/${id}/items/${itemId}/file`);
/** The ZIP goes as the raw request body (streamed to a temp file on the server, never held in memory there). */
const zipBody = (file: Blob) => ({ method: 'POST', body: file, headers: { 'Content-Type': 'application/zip' } });
const named = (path: string, file: File | Blob) => (file instanceof File && file.name ? `${path}?name=${encodeURIComponent(file.name.slice(0, 200))}` : path);
export const verifyBundle = (file: File | Blob) => api<BundleVerification>(named('cases/bundles/verify', file), zipBody(file));
export const importBundle = (file: File | Blob) => api<BundleImport>(named('cases/bundles/import', file), zipBody(file));
export const checkCaseIntegrity = (id: string) => post<CaseIntegrity>(`cases/${id}/integrity`);
